/**
 * Allure result file structure (allure-results/*.json)
 * Generated by allure-cucumberjs, allure-playwright, or any Allure adapter.
 */

export interface AllureLabel {
  name: string;
  value: string;
}

export interface AllureAttachment {
  name: string;
  /** Filename within the allure-results directory */
  source: string;
  type: string;
}

export interface AllureStatusDetails {
  message?: string;
  trace?: string;
}

export interface AllureLink {
  name?: string;
  url: string;
  type?: string;
}

export interface AllureResult {
  uuid: string;
  name: string;
  fullName?: string;
  status: 'passed' | 'failed' | 'broken' | 'skipped' | 'unknown';
  statusDetails?: AllureStatusDetails;
  labels: AllureLabel[];
  links?: AllureLink[];
  attachments: AllureAttachment[];
  start?: number;
  stop?: number;
}

export interface ParsedFailure {
  uuid: string;
  scenarioName: string;
  fullName?: string;
  errorMessage: string;
  errorTrace?: string;
  /** Jira ticket key extracted from @allure.label.issue=PROJ-123 */
  jiraTicket?: string;
  /** GitHub Issue number extracted from @allure.label.github_issue=42 */
  githubIssue?: number;
  screenshotPath?: string;
  duration?: number;
}
